696	/// Merge two `JsFileSource` values by picking the most permissive one.
697	///
698	/// Vue and Svelte files can have multiple `<script>` tags with different
699	/// `lang` attributes. The merged result is used as the base file source
700	/// for text expressions and directives, so it must be able to parse any
701	/// syntax that might appear in the template.
702	///
703	/// Hierarchy: Tsx > Ts > Jsx > JsModule > JsScript.
704	fn merge_js_file_source(a: JsFileSource, b: JsFileSource) -> JsFileSource {
705	    let ts = a.is_typescript() || b.is_typescript();
706	    let jsx = a.is_jsx() || b.is_jsx();
707	    match (ts, jsx) {
708	        (true, true) => JsFileSource::tsx(),
709	        (true, false) => JsFileSource::ts(),
710	        (false, true) => JsFileSource::jsx(),
711	        (false, false) => JsFileSource::js_module(),
712	    }
713	}
